{"version":3,"file":"index.esm.mjs","sources":["../src/utils/isCheckBoxInput.ts","../src/utils/isFileInput.ts","../src/utils/isDateObject.ts","../src/utils/isNullOrUndefined.ts","../src/utils/isObject.ts","../src/logic/getEventValue.ts","../src/utils/stringToPath.ts","../src/logic/getNullAncestorValue.ts","../src/logic/isNameInFieldArray.ts","../src/utils/isWeb.ts","../src/utils/cloneObject.ts","../src/constants.ts","../src/utils/isKey.ts","../src/utils/isUndefined.ts","../src/utils/get.ts","../src/utils/isBoolean.ts","../src/utils/isFunction.ts","../src/utils/set.ts","../src/useFormControlContext.ts","../src/logic/getProxyFormState.ts","../src/useIsomorphicLayoutEffect.ts","../src/utils/isPlainObject.ts","../src/utils/isPrimitive.ts","../src/utils/deepEqual.ts","../src/useResyncOnReconnect.ts","../src/useFormState.ts","../src/utils/isString.ts","../src/logic/generateWatchOutput.ts","../src/useWatch.ts","../src/useController.ts","../src/controller.tsx","../src/errorMessage.tsx","../src/logic/generateId.ts","../src/logic/getFocusFieldName.ts","../src/logic/getValidationModes.ts","../src/logic/isWatched.ts","../src/logic/iterateFieldsByAction.ts","../src/logic/updateFieldArrayRootError.ts","../src/utils/isEmptyObject.ts","../src/utils/isHTMLElement.ts","../src/utils/isRadioInput.ts","../src/utils/isRegex.ts","../src/logic/appendErrors.ts","../src/logic/getCheckboxValue.ts","../src/logic/getRadioValue.ts","../src/logic/getValidateError.ts","../src/logic/getValueAndMessage.ts","../src/logic/validateField.ts","../src/utils/convertToArrayPayload.ts","../src/utils/append.ts","../src/utils/fillEmptyArray.ts","../src/utils/insert.ts","../src/utils/move.ts","../src/utils/prepend.ts","../src/utils/compact.ts","../src/utils/remove.ts","../src/utils/swap.ts","../src/utils/unset.ts","../src/utils/update.ts","../src/useFieldArray.ts","../src/fieldArray.tsx","../src/utils/flatten.ts","../src/utils/formData.ts","../src/utils/json.ts","../src/utils/noop.ts","../src/useFormContext.tsx","../src/form.tsx","../src/formState.tsx","../src/utils/createSubject.ts","../src/utils/extractFormValues.ts","../src/utils/has.ts","../src/utils/isMultipleSelect.ts","../src/utils/isRadioOrCheckbox.ts","../src/utils/live.ts","../src/logic/collectDirtyFieldNames.ts","../src/utils/objectHasFunction.ts","../src/logic/getDirtyFields.ts","../src/logic/getFieldArrayItemNames.ts","../src/logic/getFieldValueAs.ts","../src/logic/getFieldValue.ts","../src/logic/getResolverOptions.ts","../src/logic/getRuleValue.ts","../src/logic/hasPromiseValidation.ts","../src/logic/hasValidation.ts","../src/logic/schemaErrorLookup.ts","../src/logic/shouldRenderFormState.ts","../src/logic/shouldSubscribeByName.ts","../src/logic/skipValidation.ts","../src/logic/unsetEmptyArray.ts","../src/logic/createFormControl.ts","../src/useForm.ts","../src/watch.tsx"],"sourcesContent":["import type { FieldElement } from '../types';\n\nexport default (element: FieldElement): element is HTMLInputElement =>\n  element.type === 'checkbox';\n","import type { FieldElement } from '../types';\n\nexport default (element: FieldElement): element is HTMLInputElement =>\n  element.type === 'file';\n","export default (value: unknown): value is Date => value instanceof Date;\n","export default (value: unknown): value is null | undefined => value == null;\n","import isDateObject from './isDateObject';\nimport isNullOrUndefined from './isNullOrUndefined';\n\nexport const isObjectType = (value: unknown): value is object =>\n  typeof value === 'object';\n\nexport default <T extends object>(value: unknown): value is T =>\n  !isNullOrUndefined(value) &&\n  !Array.isArray(value) &&\n  isObjectType(value) &&\n  !isDateObject(value);\n","import isCheckBoxInput from '../utils/isCheckBoxInput';\nimport isFileInput from '../utils/isFileInput';\nimport isObject from '../utils/isObject';\n\ntype Event = { target: any };\n\nexport default (event: unknown) =>\n  isObject(event) && (event as Event).target\n    ? isCheckBoxInput((event as Event).target)\n      ? (event as Event).target.checked\n      : isFileInput((event as Event).target)\n        ? (event as Event).target.files\n        : (event as Event).target.value\n    : event;\n","const FIELD_PATH_RE = /[.[\\]'\"]/;\n\nexport default (input: string): string[] =>\n  input.split(FIELD_PATH_RE).filter(Boolean);\n","import stringToPath from '../utils/stringToPath';\n\nexport default function getNullAncestorValue(\n  control: { _formValues: unknown; _defaultValues: unknown },\n  name: string,\n) {\n  const segments = stringToPath(name);\n  let formValues: any = control._formValues;\n  let defaultValues: any = control._defaultValues;\n\n  for (let i = 0; i < segments.length - 1; i++) {\n    const key = segments[i];\n    formValues = formValues == null ? formValues : formValues[key];\n    defaultValues = defaultValues == null ? defaultValues : defaultValues[key];\n\n    if (formValues === null || defaultValues === null) {\n      return null;\n    }\n  }\n\n  return undefined;\n}\n","import type { InternalFieldName } from '../types';\n\nexport default (names: Set<InternalFieldName>, name: InternalFieldName) =>\n  name\n    .split('.')\n    .some(\n      (part, index, arr) =>\n        !isNaN(Number(part)) && names.has(arr.slice(0, index).join('.')),\n    );\n","export default typeof window !== 'undefined' &&\n  typeof window.HTMLElement !== 'undefined' &&\n  typeof document !== 'undefined';\n","import isWeb from './isWeb';\n\nexport default function cloneObject<T>(data: T): T {\n  if (data === null || typeof data !== 'object') {\n    return data;\n  }\n\n  if (data instanceof Date) {\n    return new Date(data) as T;\n  }\n\n  const isBlobInstance = typeof Blob !== 'undefined' && data instanceof Blob;\n  const isFileListInstance =\n    typeof FileList !== 'undefined' && data instanceof FileList;\n\n  if (isWeb && (isBlobInstance || isFileListInstance)) {\n    return data;\n  }\n\n  const isArray = Array.isArray(data);\n\n  if (!isArray && (data as object).constructor !== Object) {\n    return data;\n  }\n\n  const copy = isArray ? [] : Object.create(Object.getPrototypeOf(data));\n\n  for (const key in data) {\n    if (Object.prototype.hasOwnProperty.call(data, key)) {\n      copy[key] = cloneObject(data[key]);\n    }\n  }\n\n  return copy;\n}\n","export const EVENTS = {\n  BLUR: 'blur',\n  FOCUS_OUT: 'focusout',\n  CHANGE: 'change',\n  SUBMIT: 'submit',\n  TRIGGER: 'trigger',\n  VALID: 'valid',\n} as const;\n\nexport const VALIDATION_MODE = {\n  onBlur: 'onBlur',\n  onChange: 'onChange',\n  onSubmit: 'onSubmit',\n  onTouched: 'onTouched',\n  all: 'all',\n} as const;\n\nexport const INPUT_VALIDATION_RULES = {\n  max: 'max',\n  min: 'min',\n  maxLength: 'maxLength',\n  minLength: 'minLength',\n  pattern: 'pattern',\n  required: 'required',\n  validate: 'validate',\n} as const;\n\nexport const REGISTER_VALIDATION_RULES = [\n  INPUT_VALIDATION_RULES.required,\n  INPUT_VALIDATION_RULES.min,\n  INPUT_VALIDATION_RULES.max,\n  INPUT_VALIDATION_RULES.minLength,\n  INPUT_VALIDATION_RULES.maxLength,\n  INPUT_VALIDATION_RULES.pattern,\n  INPUT_VALIDATION_RULES.validate,\n] as const;\n\nexport const FORM_ERROR_TYPE = 'form';\n\nexport const ROOT_ERROR_TYPE = 'root';\n\nexport const PROTOTYPE_KEYWORDS = ['__proto__', 'constructor', 'prototype'];\n","const IS_KEY_RE = /^\\w*$/;\n\nexport default (value: string) => IS_KEY_RE.test(value);\n","export default (val: unknown): val is undefined => val === undefined;\n","import { PROTOTYPE_KEYWORDS } from '../constants';\n\nimport isKey from './isKey';\nimport isNullOrUndefined from './isNullOrUndefined';\nimport isObject from './isObject';\nimport isUndefined from './isUndefined';\nimport stringToPath from './stringToPath';\n\nexport default <T>(\n  object: T,\n  path?: string | null,\n  defaultValue?: unknown,\n): any => {\n  if (!path || !isObject(object)) {\n    return defaultValue;\n  }\n\n  const paths = isKey(path) ? [path] : stringToPath(path);\n  if (paths.some((key) => PROTOTYPE_KEYWORDS.includes(key))) {\n    return defaultValue;\n  }\n\n  const result = paths.reduce<any>((result, key) => {\n    return isNullOrUndefined(result) ? undefined : result[key];\n  }, object);\n\n  return isUndefined(result) || result === object\n    ? isUndefined(object[path as keyof T])\n      ? defaultValue\n      : object[path as keyof T]\n    : result;\n};\n","export default (value: unknown): value is boolean => typeof value === 'boolean';\n","export default (value: unknown): value is Function =>\n  typeof value === 'function';\n","import { PROTOTYPE_KEYWORDS } from '../constants';\nimport type { FieldPath, FieldValues } from '../types';\n\nimport isKey from './isKey';\nimport isObject from './isObject';\nimport stringToPath from './stringToPath';\n\nexport default (\n  object: FieldValues,\n  path: FieldPath<FieldValues>,\n  value?: unknown,\n) => {\n  let index = -1;\n  const tempPath = isKey(path) ? [path] : stringToPath(path);\n  const length = tempPath.length;\n  const lastIndex = length - 1;\n\n  while (++index < length) {\n    const key = tempPath[index];\n    let newValue = value;\n\n    if (index !== lastIndex) {\n      const objValue = object[key];\n      newValue =\n        isObject(objValue) || Array.isArray(objValue)\n          ? objValue\n          : !isNaN(+tempPath[index + 1])\n            ? []\n            : {};\n    }\n\n    if (PROTOTYPE_KEYWORDS.includes(key)) {\n      return;\n    }\n\n    object[key] = newValue;\n    object = object[key];\n  }\n};\n","import React from 'react';\n\nimport type { Control, FieldValues } from './types';\n\n/**\n * Separate context for `control` to prevent unnecessary rerenders.\n * Internal hooks that only need control use this instead of full form context.\n */\nexport const HookFormControlContext = React.createContext<Control | null>(null);\nHookFormControlContext.displayName = 'HookFormControlContext';\n\n/**\n * @internal Internal hook to access only control from context.\n */\nexport const useFormControlContext = <\n  TFieldValues extends FieldValues,\n  TContext = any,\n  TTransformedValues = TFieldValues,\n>(): Control<TFieldValues, TContext, TTransformedValues> =>\n  React.useContext(HookFormControlContext) as Control<\n    TFieldValues,\n    TContext,\n    TTransformedValues\n  >;\n","import { VALIDATION_MODE } from '../constants';\nimport type { Control, FieldValues, FormState, ReadFormState } from '../types';\n\nexport default <\n  TFieldValues extends FieldValues,\n  TContext = unknown,\n  TTransformedValues = TFieldValues,\n>(\n  formState: FormState<TFieldValues>,\n  control: Control<TFieldValues, TContext, TTransformedValues>,\n  localProxyFormState?: ReadFormState,\n  isRoot = true,\n) => {\n  const result = {} as typeof formState;\n\n  for (const key in formState) {\n    Object.defineProperty(result, key, {\n      get: () => {\n        const _key = key as keyof FormState<TFieldValues> & keyof ReadFormState;\n\n        if (control._proxyFormState[_key] !== VALIDATION_MODE.all) {\n          control._proxyFormState[_key] = !isRoot || VALIDATION_MODE.all;\n        }\n\n        localProxyFormState && (localProxyFormState[_key] = true);\n        return formState[_key];\n      },\n    });\n  }\n\n  return result;\n};\n","import React from 'react';\n\nimport isWeb from './utils/isWeb';\n\nexport const useIsomorphicLayoutEffect = isWeb\n  ? React.useLayoutEffect\n  : React.useEffect;\n","import isObject from './isObject';\n\nexport default (tempObject: object) => {\n  const prototypeCopy =\n    tempObject.constructor && tempObject.constructor.prototype;\n\n  return (\n    isObject(prototypeCopy) && prototypeCopy.hasOwnProperty('isPrototypeOf')\n  );\n};\n","import type { Primitive } from '../types';\n\nimport isNullOrUndefined from './isNullOrUndefined';\nimport { isObjectType } from './isObject';\n\nexport default (value: unknown): value is Primitive =>\n  isNullOrUndefined(value) || !isObjectType(value);\n","import isDateObject from './isDateObject';\nimport isObject from './isObject';\nimport isPlainObject from './isPlainObject';\nimport isPrimitive from './isPrimitive';\n\nconst isEmptyObjectWithCustomPrototype = (object: object, keys: string[]) =>\n  keys.length === 0 && !Array.isArray(object) && !isPlainObject(object);\n\nexport default function deepEqual(\n  object1: unknown,\n  object2: unknown,\n  visited = new WeakMap<object, WeakSet<object>>(),\n) {\n  if (object1 === object2) {\n    return true;\n  }\n\n  if (isPrimitive(object1) || isPrimitive(object2)) {\n    return Object.is(object1, object2);\n  }\n\n  if (isDateObject(object1) && isDateObject(object2)) {\n    return Object.is(object1.getTime(), object2.getTime());\n  }\n\n  const keys1 = Object.keys(object1);\n  const keys2 = Object.keys(object2);\n\n  if (keys1.length !== keys2.length) {\n    return false;\n  }\n\n  if (\n    isEmptyObjectWithCustomPrototype(object1, keys1) ||\n    isEmptyObjectWithCustomPrototype(object2, keys2)\n  ) {\n    return Object.is(object1, object2);\n  }\n\n  if (!keys1.length && Array.isArray(object1) !== Array.isArray(object2)) {\n    return false;\n  }\n\n  const visitedPairs = visited.get(object1);\n\n  if (visitedPairs && visitedPairs.has(object2)) {\n    return true;\n  }\n\n  if (visitedPairs) {\n    visitedPairs.add(object2);\n  } else {\n    const ws = new WeakSet();\n    ws.add(object2);\n    visited.set(object1, ws);\n  }\n\n  for (const key of keys1) {\n    const val1 = (object1 as Record<string, unknown>)[key];\n\n    if (!(key in (object2 as object))) {\n      return false;\n    }\n\n    if (key !== 'ref') {\n      const val2 = (object2 as Record<string, unknown>)[key];\n\n      if (\n        (isDateObject(val1) && isDateObject(val2)) ||\n        ((isObject(val1) || Array.isArray(val1)) &&\n          (isObject(val2) || Array.isArray(val2)))\n          ? !deepEqual(val1, val2, visited)\n          : !Object.is(val1, val2)\n      ) {\n        return false;\n      }\n    }\n  }\n\n  return true;\n}\n","import React from 'react';\n\nimport cloneObject from './utils/cloneObject';\nimport deepEqual from './utils/deepEqual';\n\nexport function useResyncOnReconnect<T>(getInitialValue?: () => T) {\n  const _connected = React.useRef(false);\n  const _initialized = React.useRef(false);\n  const _prevValue = React.useRef<T | undefined>(undefined);\n  const _renderCount = React.useRef(0);\n\n  _renderCount.current++;\n\n  if (!_initialized.current && getInitialValue) {\n    _initialized.current = true;\n    _prevValue.current = cloneObject(getInitialValue());\n  }\n\n  const resyncIfNeeded = React.useCallback(\n    (\n      enabled: boolean,\n      getCurrentValue: () => T,\n      setValue: (value: T) => void,\n    ) => {\n      if (\n        enabled &&\n        (_connected.current ||\n          (_initialized.current && _renderCount.current > 1))\n      ) {\n        const currentValue = getCurrentValue();\n\n        if (!deepEqual(_prevValue.current, currentValue)) {\n          setValue(currentValue);\n        }\n      }\n\n      _connected.current = true;\n    },\n    [],\n  );\n\n  const snapshot = React.useCallback(\n    (enabled: boolean, getCurrentValue: () => T) => {\n      if (enabled) {\n        _prevValue.current = cloneObject(getCurrentValue());\n      }\n    },\n    [],\n  );\n\n  return { resyncIfNeeded, snapshot };\n}\n","import React from 'react';\n\nimport getProxyFormState from './logic/getProxyFormState';\nimport type {\n  FieldValues,\n  FormState,\n  UseFormStateProps,\n  UseFormStateReturn,\n} from './types';\nimport { useFormControlContext } from './useFormControlContext';\nimport { useIsomorphicLayoutEffect } from './useIsomorphicLayoutEffect';\nimport { useResyncOnReconnect } from './useResyncOnReconnect';\n\n/**\n * Subscribes to form state with re-renders isolated to this hook.\n * Optionally scope to specific field names to minimize re-render surface.\n *\n * @see [API](https://react-hook-form.com/docs/useformstate)\n *\n * @example\n * ```tsx\n * const { errors, isDirty } = useFormState({ control, name: \"email\" });\n * ```\n */\nexport function useFormState<\n  TFieldValues extends FieldValues = FieldValues,\n  TTransformedValues = TFieldValues,\n>(\n  props?: UseFormStateProps<TFieldValues, TTransformedValues>,\n): UseFormStateReturn<TFieldValues> {\n  const formControl = useFormControlContext<\n    TFieldValues,\n    unknown,\n    TTransformedValues\n  >();\n  const { control = formControl, disabled, name, exact } = props || {};\n\n  const getCurrentFormState = () => ({\n    ...control._formState,\n    defaultValues:\n      control._defaultValues as FormState<TFieldValues>['defaultValues'],\n  });\n\n  const [formState, updateFormState] =\n    React.useState<FormState<TFieldValues>>(getCurrentFormState);\n  const _localProxyFormState = React.useRef({\n    isDirty: false,\n    isLoading: false,\n    dirtyFields: false,\n    touchedFields: false,\n    validatingFields: false,\n    isValidating: false,\n    isValid: false,\n    errors: false,\n  });\n\n  const { resyncIfNeeded, snapshot } =\n    useResyncOnReconnect<FormState<TFieldValues>>(getCurrentFormState);\n\n  useIsomorphicLayoutEffect(() => {\n    resyncIfNeeded(!disabled, getCurrentFormState, updateFormState);\n\n    const unsubscribe = control._subscribe({\n      name,\n      formState: _localProxyFormState.current,\n      exact,\n      callback: (formState) => {\n        !disabled &&\n          updateFormState({\n            ...control._formState,\n            ...formState,\n            defaultValues:\n              control._defaultValues as FormState<TFieldValues>['defaultValues'],\n          });\n      },\n    });\n\n    return () => {\n      unsubscribe();\n      snapshot(!disabled, getCurrentFormState);\n    };\n  }, [control, name, disabled, exact, resyncIfNeeded, snapshot]);\n\n  React.useEffect(() => {\n    _localProxyFormState.current.isValid && control._setValid(true);\n  }, [control]);\n\n  return React.useMemo(\n    () =>\n      getProxyFormState(\n        formState,\n        control,\n        _localProxyFormState.current,\n        false,\n      ),\n    [formState, control],\n  );\n}\n","export default (value: unknown): value is string => typeof value === 'string';\n","import type { DeepPartial, FieldValues, Names } from '../types';\nimport get from '../utils/get';\nimport isString from '../utils/isString';\n\nexport default <T>(\n  names: string | string[] | undefined,\n  _names: Names,\n  formValues?: FieldValues,\n  isGlobal?: boolean,\n  defaultValue?: DeepPartial<T> | unknown,\n) => {\n  if (isString(names)) {\n    isGlobal && _names.watch.add(names);\n    return get(formValues, names, defaultValue);\n  }\n\n  if (Array.isArray(names)) {\n    return names.map(\n      (fieldName) => (\n        isGlobal && _names.watch.add(fieldName),\n        get(formValues, fieldName, get(defaultValue, fieldName))\n      ),\n    );\n  }\n\n  isGlobal && (_names.watchAll = true);\n\n  return formValues;\n};\n","import React from 'react';\n\nimport generateWatchOutput from './logic/generateWatchOutput';\nimport deepEqual from './utils/deepEqual';\nimport type {\n  Control,\n  DeepPartialSkipArrayKey,\n  FieldPath,\n  FieldPathValue,\n  FieldPathValues,\n  FieldValues,\n  InternalFieldName,\n  UseWatchProps,\n} from './types';\nimport { useFormControlContext } from './useFormControlContext';\nimport { useIsomorphicLayoutEffect } from './useIsomorphicLayoutEffect';\nimport { useResyncOnReconnect } from './useResyncOnReconnect';\n\n/** Watches the entire form; re-renders when any value changes. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TTransformedValues = TFieldValues,\n>(props: {\n  name?: undefined;\n  defaultValue?: DeepPartialSkipArrayKey<TFieldValues>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute?: undefined;\n}): DeepPartialSkipArrayKey<TFieldValues>;\n/** Watches a single field by name. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,\n  TTransformedValues = TFieldValues,\n>(props: {\n  name: TFieldName;\n  defaultValue?: FieldPathValue<TFieldValues, TFieldName>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute?: undefined;\n}): FieldPathValue<TFieldValues, TFieldName>;\n/** Watches the entire form and derives a value via `compute`. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TTransformedValues = TFieldValues,\n  TComputeValue = unknown,\n>(props: {\n  name?: undefined;\n  defaultValue?: DeepPartialSkipArrayKey<TFieldValues>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute: (formValues: TFieldValues) => TComputeValue;\n}): TComputeValue;\n/** Watches a single field and derives a value via `compute`. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,\n  TTransformedValues = TFieldValues,\n  TComputeValue = unknown,\n>(props: {\n  name: TFieldName;\n  defaultValue?: FieldPathValue<TFieldValues, TFieldName>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute: (\n    fieldValue: FieldPathValue<TFieldValues, TFieldName>,\n  ) => TComputeValue;\n}): TComputeValue;\n/** Watches multiple fields by name array. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldNames extends readonly FieldPath<TFieldValues>[] =\n    readonly FieldPath<TFieldValues>[],\n  TTransformedValues = TFieldValues,\n>(props: {\n  name: readonly [...TFieldNames];\n  defaultValue?: DeepPartialSkipArrayKey<TFieldValues>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute?: undefined;\n}): FieldPathValues<TFieldValues, TFieldNames>;\n/** Watches multiple fields and derives a value via `compute`. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n  TFieldNames extends readonly FieldPath<TFieldValues>[] =\n    readonly FieldPath<TFieldValues>[],\n  TTransformedValues = TFieldValues,\n  TComputeValue = unknown,\n>(props: {\n  name: readonly [...TFieldNames];\n  defaultValue?: DeepPartialSkipArrayKey<TFieldValues>;\n  control?: Control<TFieldValues, any, TTransformedValues>;\n  disabled?: boolean;\n  exact?: boolean;\n  compute: (\n    fieldValue: FieldPathValues<TFieldValues, TFieldNames>,\n  ) => TComputeValue;\n}): TComputeValue;\n/** Watches the entire form; reads `control` from `FormProvider` context. */\nexport function useWatch<\n  TFieldValues extends FieldValues = FieldValues,\n>(): DeepPartialSkipArrayKey<TFieldValues>;\n/**\n * Subscribes to field value changes and isolates re-renders to the hook level.\n *\n * @see [API](https://react-hook-form.com/docs/usewatch)\n *\n * @example\n * ```tsx\n * const email = useWatch({ control, name: \"email\" });\n * const all   = useWatch({ control });\n * const adult = useWatch({ control, name: \"age\", compute: (v) => v >= 18 });\n * ```\n */\nexport function useWatch<TFieldValues extends FieldValues>(\n  props?: UseWatchProps<TFieldValues>,\n) {\n  const formControl = useFormControlContext<TFieldValues>();\n  const {\n    control = formControl,\n    name,\n    defaultValue,\n    disabled,\n    exact,\n    compute,\n  } = props || {};\n  const _defaultValue = React.useRef(defaultValue);\n  const _compute = React.useRef(compute);\n\n  const _prevControl = React.useRef(control);\n  const _prevName = React.useRef(name);\n\n  _compute.current = compute;\n\n  const getInitialOutput = () => {\n    const defaultValue = control._getWatch(\n      name as InternalFieldName,\n      _defaultValue.current as DeepPartialSkipArrayKey<TFieldValues>,\n    );\n\n    return _compute.current ? _compute.current(defaultValue) : defaultValue;\n  };\n\n  const [value, updateValue] = React.useState(getInitialOutput);\n  const _computeFormValues = React.useRef<unknown>(value);\n\n  const getCurrentOutput = React.useCallback(\n    (values?: TFieldValues) => {\n      const formValues = generateWatchOutput(\n        name as InternalFieldName | InternalFieldName[],\n        control._names,\n        values || control._formValues,\n        false,\n        _defaultValue.current,\n      );\n\n      return _compute.current ? _compute.current(formValues) : formValues;\n    },\n    [control._formValues, control._names, name],\n  );\n\n  const refreshValue = React.useCallback(\n    (values?: TFieldValues) => {\n      if (!disabled) {\n        const formValues = generateWatchOutput(\n          name as InternalFieldName | InternalFieldName[],\n          control._names,\n          values || control._formValues,\n          false,\n          _defaultValue.current,\n        );\n\n        if (_compute.current) {\n          const computedFormValues = _compute.current(formValues);\n\n          if (!deepEqual(computedFormValues, _computeFormValues.current)) {\n            updateValue(computedFormValues);\n            _computeFormValues.current = computedFormValues;\n          }\n        } else {\n          updateValue(formValues);\n        }\n      }\n    },\n    [control._formValues, control._names, disabled, name],\n  );\n\n  const { resyncIfNeeded, snapshot } =\n    useResyncOnReconnect<unknown>(getInitialOutput);\n\n  const _refreshValue = React.useRef(refreshValue);\n  _refreshValue.current = refreshValue;\n  const _getCurrentOutput = React.useRef(getCurrentOutput);\n  _getCurrentOutput.current = getCurrentOutput;\n\n  useIsomorphicLayoutEffect(() => {\n    if (\n      _prevControl.current !== control ||\n      !deepEqual(_prevName.current, name)\n    ) {\n      _prevControl.current = control;\n      _prevName.current = name;\n      _refreshValue.current()